//! Edit presets, converted by `edits preset to-rust`: Alight Motion projects (anime edits supplied by the project
//! owner) and Premiere Pro transition presets found on GitHub (wgetgoose/AdobePresets, Deep0902, felipoliver15-hash,
//! Renderdragonorg, asDJKLFHadjksh, ZenDev-arc). Timing, speed, camera moves, shakes, blurs and flashes only:
//! no footage, no music, no original files.
#![allow(clippy::all)]
use crate::preset::{Curve, Ease, Ease::*, Flash, Motion, Preset, Slot};

fn c(k: &[(f64, f64, Ease)]) -> Curve {
    Curve { keys: k.to_vec() }
}

pub fn all() -> Vec<Preset> {
    vec![p_diwali_x_nagumo_edit(), p_edited_part_of_gojo_hollow_purple_1(), p_gojo_hollow_purple_edit(), p_kitagawa_1(), p_madara(), p_marin_lights_camera_action(), p_megumi_trend_edit(), p_new_project_124_1(), p_obito_face_revealed_edit(), p_other_half_of_obito_edit(), p_solo_jinwoo_edit(), p_tenka_2()]
}

